def solve():
    n, m = map(int, input().split())
    play_list = []
    total_duration = 0

    for _ in range(n):
        c, t = map(int, input().split())
        play_list.append((c, t))
        total_duration += c * t

    moments = list(map(int, input().split()))

    current_time = 0
    for i in range(n):
        c, t = play_list[i]
        next_time = current_time + c * t

        for j in range(m):
            if moments[j] < next_time:
                if moments[j] >= current_time:
                    remaining_time = moments[j] - current_time
                    song_number = (remaining_time // t) + 1
                    print(song_number)
            else:
                break

        current_time = next_time

solve()
